package com.vandorlabs.physics;

import java.util.*;
import com.vandorlabs.gear.core.GearMotion;

/** Checks every accepted link independently, without using the solver's tree or residual code. */
public final class CouplerGraphConstraintTest {
 private static int checks,profiles;private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Graph constraint: "+why);}
 private static CouplerArmConstraint.Stroke free(double p){return new CouplerArmConstraint.Stroke(0,1,p);}
 private static CouplerGraphConstraint.Graph graph(int bodies,int root,CouplerGraphConstraint.Link...links){return new CouplerGraphConstraint.Graph(bodies,root,Arrays.asList(links));}
 private static CouplerGraphConstraint.Link link(int a,int b){return new CouplerGraphConstraint.Link(a,b);}
 private static void exact(CouplerGraphConstraint.Graph graph,CouplerGraphConstraint.Model model,CouplerGraphConstraint.Result r,RigidTransform[] rotations){
  need(r.accepted(),"expected solution: "+r.failure+" error="+r.error);double[] phase=new double[r.arms()],points=new double[graph.links()*6];for(int i=0;i<phase.length;i++){phase[i]=r.progress(i);need(phase[i]>=0&&phase[i]<=1,"stroke bounds");}need(model.evaluate(phase,points),"independent model");for(int i=0;i<graph.links();i++){CouplerGraphConstraint.Link l=graph.link(i);RigidTransform a=r.transform(l.first),b=r.transform(l.second);double[] pa=a.point(points[i*6],points[i*6+1],points[i*6+2]),pb=b.point(points[i*6+3],points[i*6+4],points[i*6+5]);double d=0;for(int k=0;k<3;k++)d+=(pa[k]-pb[k])*(pa[k]-pb[k]);need(Math.sqrt(d)<=1e-7,"every closed head pair coincides");}for(int i=0;i<graph.bodies;i++)for(int k=0;k<9;k++)need(r.transform(i).r[k]==rotations[i].r[k],"no unrequested axis lock");RigidTransform root=r.transform(graph.root);need(root.x==0&&root.y==0&&root.z==0,"canonical root");need(r.evaluations<=CouplerGraphConstraint.MAX_EVALUATIONS,"bounded evaluations");profiles++;
 }
 private static void pair(){
  CouplerGraphConstraint.Graph g=graph(2,0,link(0,1),link(0,1));CouplerGraphConstraint.Workspace w=new CouplerGraphConstraint.Workspace(g,2);CouplerGraphConstraint.Model model=(phase,out)->{for(int i=0;i<2;i++){GearMotion.Vec p=GearMotion.pose(GearMotion.Mode.EXTEND,GearMotion.Direction.NORTH,4,phase[i]).transformFootVertex(0,0,i*4);out[i*6]=p.x;out[i*6+1]=p.y;out[i*6+2]=p.z;out[i*6+3]=out[i*6+4]=0;out[i*6+5]=i*4;}return true;};
  for(int angle=-75;angle<=75;angle+=3)for(double a:new double[]{.1,.3,.5,.8})for(double b:new double[]{.2,.4,.7,.9}){RigidTransform[] rotations={RigidTransform.IDENTITY,RigidTransform.rotation(0,0,1,angle)};CouplerGraphConstraint.Result result=CouplerGraphConstraint.solve(model,new CouplerArmConstraint.Stroke[]{free(a),free(b)},rotations,w);exact(g,model,result,rotations);}
  CouplerGraphConstraint.Result a=CouplerGraphConstraint.solve(model,new CouplerArmConstraint.Stroke[]{free(.2),free(.4)},new RigidTransform[]{RigidTransform.IDENTITY,RigidTransform.rotation(0,0,1,-40)},w),b=CouplerGraphConstraint.solve(model,new CouplerArmConstraint.Stroke[]{free(.6),free(.8)},new RigidTransform[]{RigidTransform.IDENTITY,RigidTransform.rotation(0,0,1,40)},w);need(a.accepted()&&b.accepted()&&Math.abs(a.transform(1).y-b.transform(1).y)>.5,"changed telescoping commands during Z twist");
  need(CouplerGraphConstraint.solve(model,new CouplerArmConstraint.Stroke[]{new CouplerArmConstraint.Stroke(0,.2,.1),new CouplerArmConstraint.Stroke(.8,1,.9)},new RigidTransform[]{RigidTransform.IDENTITY,RigidTransform.IDENTITY},w).failure==CouplerGraphConstraint.Failure.UNSATISFIED,"stroke exhaustion explicitly refuses");
  need(CouplerGraphConstraint.solve(model,new CouplerArmConstraint.Stroke[]{free(.2),free(.8)},new RigidTransform[]{RigidTransform.IDENTITY,RigidTransform.rotation(1,0,0,20)},w).failure==CouplerGraphConstraint.Failure.UNSATISFIED,"actual incompatible orientation refuses");
 }
 private static void graphs(){
  CouplerGraphConstraint.Graph cycle=graph(3,2,link(0,1),link(1,2),link(2,0),link(1,1));CouplerGraphConstraint.Model model=(p,out)->{Arrays.fill(out,0);out[0]=1;out[6]=2;out[12]=-p[0]*6;out[18]=p[1]-.25;return true;};RigidTransform[] rotations={RigidTransform.IDENTITY,RigidTransform.IDENTITY,RigidTransform.IDENTITY};CouplerGraphConstraint.Workspace w=new CouplerGraphConstraint.Workspace(cycle,2);CouplerGraphConstraint.Result result=CouplerGraphConstraint.solve(model,new CouplerArmConstraint.Stroke[]{free(.1),free(.8)},rotations,w);exact(cycle,model,result,rotations);need(Math.abs(result.progress(0)-.5)<1e-7&&Math.abs(result.progress(1)-.25)<1e-7,"cycle and same-body residual both constrain phases");
  // A single ordinary articulated contact imposes no orientation axis restriction.
  CouplerGraphConstraint.Graph single=graph(2,0,link(0,1));CouplerGraphConstraint.Model one=(p,out)->{out[0]=p[0]*3;out[1]=2;out[2]=-1;out[3]=4;out[4]=1;out[5]=2;return true;};w=new CouplerGraphConstraint.Workspace(single,1);for(int axis=0;axis<3;axis++)for(int angle=-75;angle<=75;angle+=5){RigidTransform[] r={RigidTransform.IDENTITY,RigidTransform.rotation(axis==0?1:0,axis==1?1:0,axis==2?1:0,angle)};result=CouplerGraphConstraint.solve(one,new CouplerArmConstraint.Stroke[]{free(.37)},r,w);exact(single,one,result,r);need(result.progress(0)==.37,"single contact keeps requested phase");}
  CouplerGraphConstraint.Graph self=graph(1,0,link(0,0));CouplerGraphConstraint.Model bad=(p,out)->{Arrays.fill(out,0);out[0]=1;return true;};need(CouplerGraphConstraint.solve(bad,new CouplerArmConstraint.Stroke[0],new RigidTransform[]{RigidTransform.IDENTITY},new CouplerGraphConstraint.Workspace(self,0)).failure==CouplerGraphConstraint.Failure.UNSATISFIED,"samebody contradictory head cannot disappear");
  need(CouplerGraphConstraint.solve(one,new CouplerArmConstraint.Stroke[]{free(.2)},new RigidTransform[]{RigidTransform.IDENTITY,RigidTransform.IDENTITY,RigidTransform.IDENTITY},new CouplerGraphConstraint.Workspace(graph(3,0,link(0,1)),1)).failure==CouplerGraphConstraint.Failure.DISCONNECTED,"disconnected explicitly refuses");
 }
 private static void guards(){
  CouplerGraphConstraint.Graph g=graph(2,0,link(0,1));CouplerGraphConstraint.Workspace w=new CouplerGraphConstraint.Workspace(g,1);RigidTransform[] r={RigidTransform.IDENTITY,RigidTransform.IDENTITY};CouplerArmConstraint.Stroke[] s={free(.2)};need(CouplerGraphConstraint.solve((p,out)->true,s,r,w).failure==CouplerGraphConstraint.Failure.MODEL,"incomplete model cannot reuse previous scratch");need(CouplerGraphConstraint.solve((p,out)->false,s,r,w).failure==CouplerGraphConstraint.Failure.MODEL,"model refusal");need(CouplerGraphConstraint.solve((p,out)->true,new CouplerArmConstraint.Stroke[]{free(Double.NaN)},r,w).failure==CouplerGraphConstraint.Failure.STROKE,"invalid stroke");need(CouplerGraphConstraint.solve((p,out)->true,s,new RigidTransform[]{RigidTransform.IDENTITY,new RigidTransform(new double[]{1,0,0,0,2,0,0,0,1},0,0,0)},w).failure==CouplerGraphConstraint.Failure.FRAME,"nonproper frame");
  CouplerGraphConstraint.Model one=(p,out)->{Arrays.fill(out,0);return true;};CouplerGraphConstraint.Result result=CouplerGraphConstraint.solve(one,s,new RigidTransform[]{RigidTransform.translation(5,6,7),RigidTransform.translation(9,8,7)},w);need(result.accepted()&&result.transform(0).x==0&&result.transform(1).x==0,"supplied translations ignored");RigidTransform copy=result.transform(1);copy.r[0]=99;need(result.transform(1).r[0]==1,"result matrix defensive");
  need(new CouplerGraphConstraint.Workspace(graph(128,0,link(0,1)),64).retainedBytes()<2000000,"workspace retained bound");
 }
 private static void allocation(){
  com.sun.management.ThreadMXBean bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();bean.setThreadAllocatedMemoryEnabled(true);final long id=Thread.currentThread().getId();final long[] previous={-1},bytes={0};final int[] calls={0};
  CouplerGraphConstraint.Model model=(p,out)->{long now=bean.getThreadAllocatedBytes(id);if(previous[0]>=0)bytes[0]+=now-previous[0];Arrays.fill(out,0);out[0]=p[0]*p[0]-.25;calls[0]++;previous[0]=bean.getThreadAllocatedBytes(id);return true;};
  CouplerGraphConstraint.Workspace w=new CouplerGraphConstraint.Workspace(graph(1,0,link(0,0)),1);CouplerArmConstraint.Stroke[] strokes={free(.8)};RigidTransform[] rotations={RigidTransform.IDENTITY};for(int i=0;i<2000;i++){previous[0]=-1;CouplerGraphConstraint.solve(model,strokes,rotations,w);}bytes[0]=0;calls[0]=0;for(int i=0;i<1000;i++){previous[0]=-1;need(CouplerGraphConstraint.solve(model,strokes,rotations,w).accepted(),"warm nonlinear fit");}need(bytes[0]==0,"between-model trial work allocates zero bytes: "+bytes[0]);System.out.println("Coupler graph warmed solver trial allocation="+bytes[0]+" bytes modelCalls="+calls[0]+" (accepted results excluded)");
 }
 public static void main(String[] args){pair();graphs();guards();allocation();System.out.println("Coupler graph constraint PASS profiles="+profiles+" checks="+checks+" Ztwist/telescoping/controls/otheraxes/cycles/parallel/samebody/refusal; runtime unbound");}
}
